  "concept_name": "Equations show mathematical balance",
  "explanation": "A linear equation is a statement that two expressions are equal to each other. The equals sign means that both sides must have the exact same value. We use equations to find the unknown number that makes the statement true.",
  "key_idea": "An equation is a statement of equality that must always remain balanced.",
  "visual_hint": "balance_scale"
}
